result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/src/molar-mass.ts", "content": "/**
 * Molar-mass calculator: tokenizer + recursive-descent parser for
 * chemical formulas supporting nested parentheses, integer multipliers
 * (e.g. Fe2(SO4)3) and dot-hydrate notation (e.g. CuSO4.5H2O).
 */

export const WEIGHTS: Record<string, number> = {
  H: 1.008,
  C: 12.011,
  N: 14.007,
  O: 15.999,
  Na: 22.99,
  S: 32.06,
  Fe: 55.845,
  Cu: 63.546,
};

// ---------------- Tokenizer ----------------

type TokenType = "element" | "number" | "lparen" | "rparen" | "dot";

interface Token {
  type: TokenType;
  value: string;
  pos: number; // index in the source string, for error messages
}

export class FormulaError extends Error {
  constructor(
    message: string,
    public readonly position?: number,
  ) {
    super(message);
    this.name = "FormulaError";
  }
}

const ELEMENT_RE = /^[A-Z][a-z]?/;
const NUMBER_RE = /^[0-9]+/;

export function tokenize(formula: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;

  while (i < formula.length) {
    const ch = formula[i];

    if (ch === "(") {
      tokens.push({ type: "lparen", value: ch, pos: i });
      i++;
    } else if (ch === ")") {
      tokens.push({ type: "rparen", value: ch, pos: i });
      i++;
    } else if (ch === "." || ch === "\u00b7") {
      // accept both ASCII '.' and the middle-dot '·' hydrate separator
      tokens.push({ type: "dot", value: ".", pos: i });
      i++;
    } else if (ch >= "A" && ch <= "Z") {
      const m = ELEMENT_RE.exec(formula.slice(i));
      tokens.push({ type: "element", value: m![0], pos: i });
      i += m![0].length;
    } else if (ch >= "0" && ch <= "9") {
      const m = NUMBER_RE.exec(formula.slice(i));
      tokens.push({ type: "number", value: m![0], pos: i });
      i += m![0].length;
    } else if (ch === " " || ch === "\t") {
      i++; // tolerate whitespace
    } else {
      throw new FormulaError(
        `Unexpected character '${ch}' at position ${i} in formula '${formula}'`,
        i,
      );
    }
  }

  return tokens;
}

// ---------------- Parser (recursive descent) ----------------
//
//   formula := term ("." multiplier? term)*
//   term    := group count?
//   group   := element | "(" formula ")"
//
// Each parse node returns its mass contribution directly.

class Parser {
  private pos = 0;

  constructor(
    private readonly tokens: Token[],
    private readonly formula: string,
  ) {}

  private peek(): Token | undefined {
    return this.tokens[this.pos];
  }

  private next(): Token {
    const tok = this.peek();
    if (!tok) {
      throw new FormulaError(`Unexpected end of formula '${this.formula}'`);
    }
    this.pos++;
    return tok;
  }

  /** formula := term ("." multiplier? term)* */
  parseFormula(): number {
    let total = this.parseTerm();
    while (this.peek()?.type === "dot") {
      this.next(); // consume '.'
      // optional hydrate multiplier, e.g. CuSO4.5H2O
      const mult = this.parseCount(1);
      total += mult * this.parseTerm();
    }
    return total;
  }

  /** term := (element | "(" formula ")") count? */
  private parseTerm(): number {
    const tok = this.next();

    let unitMass: number;
    if (tok.type === "lparen") {
      unitMass = this.parseFormula();
      const close = this.next();
      if (close.type !== "rparen") {
        throw new FormulaError(
          `Expected ')' at position ${close.pos} in formula '${this.formula}', found '${close.value}'`,
          close.pos,
        );
      }
    } else if (tok.type === "element") {
      if (!(tok.value in WEIGHTS)) {
        throw new FormulaError(
          `Unknown element '${tok.value}' at position ${tok.pos} in formula '${this.formula}'`,
          tok.pos,
        );
      }
      unitMass = WEIGHTS[tok.value];
    } else {
      throw new FormulaError(
        `Expected element or '(' at position ${tok.pos} in formula '${this.formula}', found '${tok.value}'`,
        tok.pos,
      );
    }

    return unitMass * this.parseCount(1);
  }

  /** Optional integer multiplier. Returns `fallback` when absent. */
  private parseCount(fallback: number): number {
    const tok = this.peek();
    if (tok?.type !== "number") return fallback;
    this.next();
    const n = Number.parseInt(tok.value, 10);
    if (!Number.isInteger(n) || n < 1) {
      throw new FormulaError(
        `Invalid multiplier '${tok.value}' at position ${tok.pos}`,
        tok.pos,
      );
    }
    return n;
  }

  atEnd(): boolean {
    return this.pos >= this.tokens.length;
  }
}

// ---------------- Public API ----------------

/** Compute the molar mass (g/mol) of a chemical formula string. */
export function molarMass(formula: string): number {
  if (typeof formula !== "string") {
    throw new FormulaError("Formula must be a string");
  }
  const trimmed = formula.trim();
  if (trimmed.length === 0) {
    throw new FormulaError("Formula is empty; expected e.g. 'H2O'");
  }

  const tokens = tokenize(trimmed);
  const parser = new Parser(tokens, trimmed);
  const mass = parser.parseFormula();

  const trailing = parser["peek"]?.() ?? undefined;
  if (!parser.atEnd()) {
    throw new FormulaError(
      `Unexpected token '${trailing!.value}' at position ${trailing!.pos} in formula '${formula}'`,
      trailing!.pos,
    );
  }

  return mass;
}
