    ["Fe2(SO4)3", 399.858],
    ["C6H12O6", 180.156],
    ["CuSO4.5H2O", 249.677],
  ])("%s -> %f", (formula, expected) => {
    expect(molarMass(formula)).toBeCloseTo(expected, 2);
  });

  it("also accepts middle-dot hydrate notation", () => {
    expect(molarMass("CuSO4\u00b75H2O")).toBeCloseTo(249.677, 2);
  });

  it("simple water sanity check", () => {
    expect(molarMass("H2O")).toBeCloseTo(18.015, 2);
  });
});

describe("molarMass — error cases", () => {
  it("rejects unknown element 'Xx2'", () => {
    expect(() => molarMass("Xx2")).toThrow(FormulaError);
    expect(() => molarMass("Xx2")).toThrow(/Unknown element 'Xx'/);
