    expect(() => molarMass("Ca(OH")).toThrow(FormulaError);
    expect(() => molarMass("Ca(OH")).toThrow(/Unexpected end of formula/);
  });

  it("rejects empty formula ''", () => {
    expect(() => molarMass("")).toThrow(FormulaError);
    expect(() => molarMass("")).toThrow(/empty/i);
  });
});
